import {renderAIChat,installAI,mountAI,resetAI} from './ai-chat.mjs';
import {renderWorkspace,installWorkspace,mountWorkspace,releaseWorkspace,resetEvidence} from './workspace.mjs';
import {renderLanding} from './landing.mjs';
import {freshState,parseState,dayKey,validProfile,makePlan,dailyLoad,summary,MODES,TEAMS,ROLES,FOCI} from './engine.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 10h12m-5-5 5 5-5 5',home:'m3 9 7-6 7 6v9H3zm5 9v-6h4v6',plan:'M5 3h10v15H5zm3 4h4m-4 4h4m-4 4h3',chat:'M3 3h14v11H8l-5 4z',play:'M7 4v12l10-6z',chart:'M3 3v14h15M7 13V9m4 4V5m4 8V7',settings:'M10 3v2m0 10v2M3 10h2m10 0h2M5 5l1 1m8 8 1 1M5 15l1-1m8-8 1-1M13 10a3 3 0 1 1-6 0 3 3 0 1 1 6 0',check:'m4 10 4 4 8-9',close:'m5 5 10 10M15 5 5 15',upload:'M10 14V3m-4 4 4-4 4 4M3 13v4h14v-4',book:'M10 5C7 2 3 3 3 3v14s4-1 7 1c3-2 7-1 7-1V3s-4-1-7 2zm0 0v13',sun:'M10 2v2m0 12v2M2 10h2m12 0h2M4 4l2 2m8 8 2 2M4 16l2-2m8-8 2-2M13 10a3 3 0 1 1-6 0 3 3 0 1 1 6 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const logo=`<a class="logo" href="#home"><img src="mark.svg" alt=""><span class="brand-name">FORTNITE<small>AI COACH</small></span><span style="color:var(--muted);font-size:9px;letter-spacing:0">α</span></a>`;
let state=freshState(),loadError=false,storageFailed=false,mediaUrl=null;
try{const s=localStorage.getItem('nextdrop.v1');if(s)state=parseState(s);}catch{loadError=true;}
function save(){try{localStorage.setItem('nextdrop.v1',JSON.stringify(state));return true;}catch{storageFailed=true;toast('Не удалось сохранить в браузере. Экспортируй данные в настройках.');return false;}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const labels={dashboard:'Кабинет',plan:'Мой план',coach:'Тренер',review:'Разбор момента',journal:'Журнал',settings:'Профиль и данные'};
const navs=[['dashboard','home','Кабинет'],['plan','plan','План'],['coach','chat','Тренер'],['review','play','Разбор'],['journal','chart','Журнал'],['settings','settings','Профиль']];
function go(v){location.hash=v;}
function landing(){return renderLanding(state,logo,icon);}
function pagehead(title,sub){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div><span class="badge lime"><i class="dot"></i> МОЯ ПРАКТИКА</span></div>`;}
function dashboard(){
 const p=state.profile,saved=state.checkins[dayKey()],check=saved||{energy:3,sleep:8};
 const light=saved&&dailyLoad(saved)==='light';
 const planned=makePlan(p,saved||{}).reduce((n,t)=>n+t.minutes,0);
 const explanation=!saved?'Сохрани сон и энергию, чтобы подобрать объём работы на сегодня.':light?'Сегодня лёгкий режим: до '+planned+' минут на спокойный разбор и запись наблюдений. Игровую практику можно отложить.':'Сегодня обычный режим: до '+planned+' минут на разбор, проверку решения и итог.';
 return `<div class="workspace"><div class="ws-heading"><div><h1>За работу, ${esc(p.nick)}.</h1><p>${esc(p.mode)} · ${esc(p.team)} · ${esc(p.focus)}</p></div></div><div class="grid-main"><section class="card"><span class="badge lime">СЛЕДУЮЩИЙ ШАГ</span><h2>Открой свой разбор</h2><p>Прикрепи клип или скрин результата, опиши момент и ответь на вопросы. Затем выбери одно изменение для практики и запиши итог.</p><a class="btn" href="#plan">${state.cases?.length?'Продолжить мой разбор':'Добавить первый момент'} →</a><p>Материал, диалог и результат находятся на одной странице.</p><p>${esc(summary(state))}</p><a href="#journal">Открыть журнал →</a></section><section class="card"><h2>Как ты сегодня?</h2><p>Это влияет на объём сегодняшней практики и подсказку тренеру.</p><form id="checkin-form"><div class="field"><label for="sleep">Сон, часов</label><input id="sleep" name="sleep" type="number" min="0" max="24" step="0.5" value="${esc(check.sleep)}" required></div><div class="field"><label for="energy">Энергия: <output id="energy-value">${esc(check.energy)}</output> из 5</label><input id="energy" name="energy" type="range" min="1" max="5" value="${esc(check.energy)}"></div><button id="checkin-save" class="btn secondary" type="submit" ${saved?'disabled':''}>${saved?'Сохранено на сегодня':'Сохранить самочувствие'}</button></form><p id="checkin-result" role="status"><strong>${saved?'Сохранено: '+saved.sleep+' ч сна · энергия '+saved.energy+'/5.':'Пока не сохранено.'}</strong> ${explanation}</p><a href="#plan">Посмотреть сегодняшний шаг →</a></section></div></div>`;
}
function planPage(){return renderWorkspace();}
function coachPage(){return renderAIChat();}
function reviewPage(){return renderWorkspace();}
function journalPage(){const games=state.sessions.reduce((n,x)=>n+x.matches,0),early=state.sessions.reduce((n,x)=>n+x.early,0);return `${pagehead('Журнал практики','Записывай наблюдения. Так появляется основа для следующего решения.')}<div class="metrics"><div class="metric"><strong>${state.sessions.length}</strong><span>Записей в журнале</span></div><div class="metric"><strong>${games}</strong><span>Матчей по твоим данным</span></div><div class="metric"><strong>${games?Math.round(early/games*100)+'%':'—'}</strong><span>Матчи с ранним вылетом</span><p class="metric-help">Доля игр, где ты или вся команда выбыли в начале матча. По твоим отметкам в журнале.</p></div></div><div class="grid-main"><section class="card"><h2>Последние сессии</h2>${state.sessions.length?state.sessions.map((s,i)=>`<article class="session"><div class="session-top"><h3>${esc(s.date)} · ${esc(s.type)}</h3><button data-delete-session="${i}" aria-label="Удалить запись от ${esc(s.date)}">Удалить</button></div>${s.caseId?`<button class="btn secondary small" data-ws-open="${esc(s.caseId)}">Открыть материал и обсуждение →</button>`:`<div class="tagrow"><span class="badge">${s.matches} матчей</span><span class="badge">${s.early} ранних вылетов</span></div>`}<p style="white-space:pre-wrap">${esc(s.note)}</p></article>`).join(''):`<div class="empty">${icon('book')}<h3>Начни с сегодняшней практики</h3><p>Запиши одну ситуацию и своё решение. Здесь появится история твоей работы.</p></div>`}</section><section class="card"><h3>Добавить сессию</h3><form id="session-form"><div class="field"><label for="session-date">Дата</label><input id="session-date" name="date" type="date" value="${dayKey()}" max="${dayKey()}" required></div><div class="field"><label for="session-type">Тип практики</label><select id="session-type" name="type"><option>Турнир</option><option>Кастомки</option><option>Ranked</option><option>Тренировка</option><option>Разбор записи</option></select></div><div class="form-grid"><div class="field"><label for="matches">Матчей</label><input id="matches" name="matches" type="number" min="0" max="100" required></div><div class="field"><label for="early">Сколько матчей закончились ранним вылетом?</label><input id="early" name="early" aria-describedby="early-help" type="number" min="0" max="100" required></div></div><div class="field"><p id="early-help" class="metric-help">Ранний вылет — полное выбытие тебя в Solo или всей команды в начале игры: на высадке, во время первого лута или файта за локу. Нок и смерть с последующим возрождением не считаются. Это твоя оценка, без фиксированного таймера.</p><label for="session-note">Что проверял, что увидел, что дальше?</label><textarea id="session-note" name="note" maxlength="3000" required></textarea></div><p class="error" id="session-error" role="alert"></p><button class="btn small" type="submit">Сохранить сессию</button></form></section></div>`;}
function settingsPage(){const p=state.profile;return `${pagehead('Твой профиль','Данные, на которых строится первая версия плана.')}<div class="grid-main"><div class="stack"><section class="card"><div class="card-top"><h2>${esc(p.nick)}</h2><button class="btn secondary small" data-action="edit-profile">Изменить</button></div><div class="tagrow">${[p.mode,p.team,p.build,p.team==='Solo'?'Все роли':p.role,`${p.minutes} мин`].map(t=>`<span class="badge">${esc(t)}</span>`).join('')}</div><p>Фокус: ${esc(p.focus)}.</p></section><section class="card"><h3>Турнирные показатели</h3><p>Введённые тобой значения. Автоматическая проверка пока не подключена. Пустое поле означает «нет данных».</p><form id="stats-form"><div class="form-grid">${[['pr','Power Ranking'],['earnings','Призовые, USD'],['events','Турнирных сессий']].map(([k,l])=>`<div class="field"><label for="stat-${k}">${l}</label><input id="stat-${k}" name="${k}" type="number" min="0" max="1000000000" step="${k==='earnings'?'0.01':'1'}" value="${state.stats[k]??''}"></div>`).join('')}</div><button class="btn secondary small" type="submit">Сохранить показатели</button></form></section><section class="card"><h3>Ссылки на твои профили</h3><p>Сохраняются как ссылки для проверки. Страницы не скачиваются автоматически.</p><form id="links-form"><div class="field"><label for="tracker">Fortnite Tracker</label><input id="tracker" name="tracker" type="url" value="${esc(p.tracker||'')}" placeholder="https://fortnitetracker.com/fortnite/profile/…"></div><div class="field"><label for="osirion">Osirion</label><input id="osirion" name="osirion" type="url" value="${esc(p.osirion||'')}" placeholder="https://osirion.gg/…"></div><p id="links-error" class="error" role="alert"></p><button class="btn secondary small" type="submit">Сохранить ссылки</button></form>${[['tracker','Открыть Fortnite Tracker'],['osirion','Открыть Osirion']].filter(([k])=>safeProfileURL(p[k],k)).map(([k,t])=>`<a class="source-link" href="${esc(p[k])}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</section></div><aside class="stack"><section class="card"><h3>Сохранение и перенос</h3><p>Профиль, журнал и диалог хранятся только в этом браузере. Сделай резервную копию для переноса на другой девайс.</p><button class="btn secondary small" data-action="export">Экспортировать JSON</button><div class="field" style="margin-top:22px"><label for="import">Импортировать резервную копию</label><input type="file" id="import" accept="application/json,.json"></div><p class="fine">Импорт заменит текущий профиль после подтверждения. Медиафайлы в копию не входят.</p></section><section class="card"><h3>Состояние базы</h3><span class="badge amber">Требует проверки</span><p style="margin-top:15px">Мета сезона и автоматический монитор обновлений ещё не подключены. Сезонные советы отключены.</p><a class="source-link" href="https://www.fortnite.com/news" target="_blank" rel="noopener noreferrer">Официальные обновления ↗</a><a class="source-link" href="https://www.fortnite.com/competitive" target="_blank" rel="noopener noreferrer">Fortnite Competitive ↗</a></section><section class="card"><h3>Удаление данных</h3><p>Удалит профиль, диалог и журнал из этого браузера.</p><button class="btn danger small" data-action="reset">Удалить мои данные</button></section></aside></div>`;}
function safeProfileURL(value,type){if(!value)return false;try{const u=new URL(value);return u.protocol==='https:'&&[type==='tracker'?'fortnitetracker.com':'osirion.gg',type==='tracker'?'www.fortnitetracker.com':'www.osirion.gg'].includes(u.hostname)&&!u.username&&!u.password;}catch{return false;}}
function render(){releaseWorkspace();let route=location.hash.slice(1)||'home';const home=['home','how','principles','faq'].includes(route);if(!home&&!state.profile){location.hash='home';return;}if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(home){$('#app').innerHTML=landing();if(route!=='home')requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView());}else{if(!labels[route])route='dashboard';const pages={dashboard,plan:planPage,coach:coachPage,review:reviewPage,journal:journalPage,settings:settingsPage};$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${logo}<div><p class="nav-label">ТВОЯ РАБОЧАЯ ЗОНА</p><nav class="sidenav">${navs.map(([id,i,l])=>`<a href="#${id}" class="navitem ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('')}</nav></div><div class="side-bottom"><span class="badge lime">FORTNITE AI COACH · ALPHA</span><p>Твоя работа.<br>Твой следующий шаг.</p><a href="#home">О проекте ↗</a></div></aside><main class="main"><header class="appbar"><span class="crumb">Рабочая зона / ${labels[route]}</span><a href="#home" class="mobile-brand">FORTNITE AI COACH ↗</a><div class="userchip"><span>${esc(state.profile.nick)}</span><a href="#settings" class="avatar" aria-label="Открыть профиль">${esc(state.profile.nick.slice(0,1).toUpperCase())}</a></div></header>${pages[route]()}</main></div>`;if(['plan','review'].includes(route))requestAnimationFrame(()=>mountWorkspace());if(route==='coach')requestAnimationFrame(()=>mountAI());}if(storageFailed)toast('Сохранение недоступно. Сделай экспорт данных.');}
let step=0,draft={};
function onboarding(edit=false){step=0;draft=edit?{...state.profile}:{nick:'',mode:'Battle Royale',team:'Solo',build:'Build',role:'IGL',focus:FOCI[0],minutes:40};renderOnboarding();$('#onboarding').showModal();}
const options=(key,values)=>`<div class="options">${values.map(v=>`<button type="button" class="option ${String(draft[key])===String(v)?'selected':''}" data-option="${key}" data-value="${v}" aria-pressed="${String(draft[key])===String(v)}">${typeof v==='number'?`${v} мин`:v}</button>`).join('')}</div>`;
function renderOnboarding(){const titles=['С чего начинаем?','Твоя роль в игре','На чём сосредоточимся?','План, который впишется в день'];const desc=['Никнейм нужен для профиля. Проверка Epic-аккаунта пока не выполняется.','Выбери формат, под который нужна практика. Обязанности внутри команды уточняются отдельно.','Не знаешь, что проседает? Выбери общий импрув — начнём с наблюдений за твоей игрой.','Выбери комфортное время на одну сессию. Позже учтём сегодняшнюю энергию.'];let content='';if(step===0)content=`<div class="field"><label for="nick">Твой Epic-никнейм</label><input id="nick" maxlength="32" autocomplete="nickname" value="${esc(draft.nick)}" placeholder="Как к тебе обращаться?" required></div><div class="field-label">Режим</div>${options('mode',MODES)}<div class="field-label">Строительство</div>${options('build',['Build','Zero Build'])}`;if(step===1)content=`<div class="field-label">Состав</div>${options('team',TEAMS)}${draft.team==='Solo'?'<div class="notice">В Solo ты принимаешь решения, файтишь и отвечаешь за собственную игру. Отдельную командную роль выбирать не нужно.</div>':`<div class="field-label">Твоя основная роль</div>${options('role',draft.team==='Duo'?['IGL','Фраггер']:ROLES)}<p class="fine">Саппорт в Trio рассматривается как второй фраггер. Конкретные обязанности зависят от договорённостей команды.</p>`}`;if(step===2)content=`<div class="field-label">Что сейчас чаще вызывает вопросы?</div>${options('focus',draft.team==='Solo'?FOCI.filter(x=>x!=='Коммуникация'):FOCI)}`;if(step===3)content=`${options('minutes',[20,40,60,90])}<div class="notice">Дисциплина — выполнять осмысленный план и честно разбирать результат. Отдых тоже часть работы. Здесь нет штрафа за пропущенный день.</div><p class="fine">Первая версия сохраняет данные в этом браузере. В разделе «Тренер» можно включить локальную языковую модель для свободного общения. Она требует скачивания и совместимого устройства.</p>`;$('#onboarding').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><span>ТВОЯ ОТПРАВНАЯ ТОЧКА / ${step+1} ИЗ 4</span><button class="close" data-action="close-dialog" aria-label="Закрыть опрос">${icon('close')}</button></div><div class="steps">${[0,1,2,3].map(i=>`<span class="${i<=step?'current':''}"></span>`).join('')}</div><h2 id="onboard-title">${titles[step]}</h2><p>${desc[step]}</p>${content}<p class="error" id="onboard-error" role="alert"></p><div class="dialog-actions"><button class="btn ghost" data-action="previous-step">${step?'← Назад':'Позже'}</button><button class="btn small" data-action="next-step">${step===3?'Создать мой план':'Продолжить'} ${icon('arrow')}</button></div></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='start'){state.profile?go('dashboard'):onboarding();}if(a==='edit-profile')onboarding(true);if(a==='close-dialog')$('#onboarding').close();if(a==='previous-step'){if(!step)$('#onboarding').close();else{step--;renderOnboarding();}}if(a==='next-step'){if(step===0){draft.nick=$('#nick').value.trim();if(!draft.nick){$('#onboard-error').textContent='Укажи никнейм, чтобы продолжить.';$('#nick').focus();return;}}if(step<3){step++;renderOnboarding();}else if(validProfile(draft)){state.profile={...draft,minutes:Number(draft.minutes)};save();$('#onboarding').close();if(location.hash==='#dashboard')render();else go('dashboard');toast('Профиль готов. Начнём с одной задачи.');}}if(b.dataset.option){if($('#nick'))draft.nick=$('#nick').value;draft[b.dataset.option]=b.dataset.option==='minutes'?Number(b.dataset.value):b.dataset.value;if(draft.team==='Solo'&&draft.focus==='Коммуникация')draft.focus='Ротации';if(draft.team==='Duo'&&draft.role==='Саппорт')draft.role='Фраггер';renderOnboarding();}if(b.dataset.toggle){const key=dayKey(),id=b.dataset.toggle;const done=state.completed[key]||[];state.completed[key]=done.includes(id)?done.filter(x=>x!==id):[...done,id];save();render();}if(b.dataset.prompt){$('#chat-message').value=b.dataset.prompt;$('#chat-message').focus();}if(b.dataset.deleteSession!==undefined&&confirm('Удалить эту запись?')){state.sessions.splice(Number(b.dataset.deleteSession),1);save();render();}if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`nextdrop-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='reset'&&confirm('Удалить весь профиль, журнал и диалог из этого браузера?')){try{localStorage.removeItem('nextdrop.v1');}catch{}resetAI();state=freshState();resetEvidence();go('home');toast('Локальные данные удалены.');}});
document.addEventListener('input',e=>{if(e.target.id==='energy')$('#energy-value').textContent=e.target.value;if(['energy','sleep'].includes(e.target.id)){const b=$('#checkin-save');if(b){b.disabled=false;b.textContent='Сохранить изменения';}const result=$('#checkin-result');if(result)result.textContent='Изменения ещё не сохранены. План обновится после сохранения.';}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='checkin-form'){const sleep=Number(d.get('sleep')),energy=Number(d.get('energy'));if(!Number.isFinite(sleep)||sleep<0||sleep>24||!Number.isInteger(energy)||energy<1||energy>5)return;state.checkins[dayKey()]={sleep,energy};if(save()){render();toast('\u0421\u0430\u043c\u043e\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e. \u041f\u043b\u0430\u043d \u043d\u0430 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043e\u0431\u043d\u043e\u0432\u043b\u0451\u043d.');}}if(f.id==='review-form'){state.review={stage:d.get('stage'),note:String(d.get('note')).trim()};if(save())toast('Описание сохранено. Файл остаётся только в текущем просмотре.');}if(f.id==='session-form'){const matches=Number(d.get('matches')),early=Number(d.get('early'));if(!Number.isInteger(matches)||!Number.isInteger(early)||early>matches){$('#session-error').textContent='Матчи должны быть целыми числами. Ранних вылетов не может быть больше сыгранных матчей.';return;}state.sessions.unshift({date:d.get('date'),type:d.get('type'),matches,early,note:String(d.get('note')).trim()});state.sessions=state.sessions.slice(0,365);save();render();toast('Запись добавлена.');}if(f.id==='stats-form'){for(const k of ['pr','earnings','events'])state.stats[k]=d.get(k)===''?null:Number(d.get(k));if(save())toast('Показатели сохранены как введённые тобой.');}if(f.id==='links-form'){for(const k of ['tracker','osirion']){const val=String(d.get(k)).trim();if(val&&!safeProfileURL(val,k)){$('#links-error').textContent=`Нужна HTTPS-ссылка на ${k==='tracker'?'fortnitetracker.com':'osirion.gg'}.`;return;}}for(const k of ['tracker','osirion'])state.profile[k]=String(d.get(k)).trim();save();render();toast('Ссылки сохранены.');}});
document.addEventListener('change',async e=>{if(e.target.id==='import'){const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('Копия слишком большая: максимум 2 МБ.');return;}try{const incoming=parseState(await file.text());if(confirm(`Заменить текущие данные профилем ${incoming.profile.nick}?`)){resetAI();state=incoming;save();render();toast('Данные восстановлены.');}}catch(err){toast('Не удалось прочитать копию: '+err.message);}}if(e.target.id==='attachment'){const file=e.target.files[0];if(!file)return;const preview=$('#file-preview');preview.replaceChildren();if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(file.size>100*1024*1024){toast('Выбери отдельный фрагмент до 100 МБ.');e.target.value='';return;}const name=document.createElement('p');name.className='fine';name.textContent=`${file.name} · ${(file.size/1048576).toFixed(1)} МБ · только локальный просмотр`;preview.append(name);if(/\.(mp4|webm)$/i.test(file.name)&&file.type.startsWith('video/')){mediaUrl=URL.createObjectURL(file);const v=document.createElement('video');v.controls=true;v.src=mediaUrl;v.className='media-preview';v.preload='metadata';v.addEventListener('error',()=>toast('Браузер не смог воспроизвести этот формат.'));preview.append(v);}else if(/^image\/(png|jpeg|webp)$/.test(file.type)){mediaUrl=URL.createObjectURL(file);const img=document.createElement('img');img.src=mediaUrl;img.alt='Прикреплённый скриншот';img.className='media-preview';preview.append(img);}else{const note=document.createElement('p');note.className='notice';note.textContent=/\.replay$/i.test(file.name)?'Файл выбран, но парсер .replay ещё не подключён. Для просмотра добавь видеофрагмент.':'Этот формат не поддерживается для просмотра. Выбери MP4, WebM, PNG, JPEG или WebP.';preview.append(note);}}});
installWorkspace({getState:()=>state,save,render,toast});
installAI({getState:()=>state,save,render,toast});
window.addEventListener('hashchange',()=>{render();if(!['#how','#principles','#faq'].includes(location.hash))window.scrollTo(0,0);});render();if(loadError)toast('Сохранение не удалось прочитать. Исходная запись не удалена.');
